import sympy

# Top-level setup
# Witness is expected to be a tuple of integers (n, m, k, a) representing:
# R = Z/nZ  (where n=0 means Z)
# S = Z/mZ  (where m=0 means Z)
# f: R -> S given by f(x) = kx
# I = aR (ideal generated by a)

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, dict):
            n = int(witness.get('n', 0))
            m = int(witness.get('m', 0))
            k = int(witness.get('k', 1))
            a = int(witness.get('a', 0))
        else:
            n, m, k, a = [int(x) for x in witness]
            
        # H_1: R and S are rings
        h1 = (n >= 0) and (m >= 0)
        
        # H_2: f: R -> S is a ring homomorphism
        if m > 0:
            well_defined = ((n * k) % m == 0)
            preserves_id = (k % m == 1 % m)
        else:
            well_defined = ((n * k) == 0)
            preserves_id = (k == 1)
            
        h2 = well_defined and preserves_id
        
        # H_3: I is an ideal of R
        h3 = (a >= 0)
        
        # ¬Q: There does not exist a unique ring homomorphism f_bar: R/I -> S
        # such that f(x) = f_bar(x + I) for all x in R.
        # This fails iff I is not a subset of ker(f), which means f(a) != 0.
        if m > 0:
            neg_q = ((k * a) % m != 0)
        else:
            neg_q = ((k * a) != 0)
            
        return [h1, h2, h3, neg_q]
    except Exception:
        return [False, False, False, False]

CONDITION_LABELS = [
    "H_1: R and S are rings",
    "H_2: f: R -> S is a ring homomorphism",
    "H_3: I is an ideal of R",
    "¬Q: There does not exist a unique ring homomorphism f_bar: R/I -> S such that f(x) = f_bar(x + I)"
]

